#!/usr/bin/env python3
"""Compliance Requirements Checker

Maps security controls to regulatory requirements,
helping organizations identify compliance gaps.
"""

COMPLIANCE_CONTROLS = {
    'PCI_DSS': {
        'network_security': {
            'firewall_config': 'Install and maintain a firewall configuration to protect cardholder data',
            'default_passwords': 'Change vendor-supplied defaults',
            'restrict_access': 'Restrict access to cardholder data by business need-to-know'
        },
        'data_protection': {
            'encrypt_transmission': 'Encrypt transmission of cardholder data across open networks',
            'encrypt_storage': 'Protect stored cardholder data',
            'key_management': 'Document and distribute encryption keys'
        },
        'vulnerability_management': {
            'antivirus': 'Maintain anti-virus software',
            'secure_systems': 'Develop and maintain secure systems',
            'vuln_scanning': 'Test security systems regularly'
        }
    },
    'HIPAA': {
        'administrative': {
            'risk_assessment': 'Conduct risk analysis',
            'training': 'Implement security awareness training',
            'incident_response': 'Establish incident response procedures'
        },
        'physical': {
            'access_control': 'Implement physical access controls',
            'workstation_security': 'Implement workstation security measures'
        },
        'technical': {
            'access_controls': 'Implement technical access controls',
            'audit_logs': 'Implement audit controls',
            'encryption': 'Implement encryption for PHI'
        }
    },
    'GDPR': {
        'data_principles': {
            'lawful_basis': 'Process data only with lawful basis',
            'data_minimization': 'Collect only necessary data',
            'purpose_limitation': 'Use data only for stated purposes'
        },
        'individual_rights': {
            'access': 'Enable data subject access requests',
            'erasure': 'Enable right to be forgotten',
            'portability': 'Enable data portability'
        },
        'security': {
            'breach_notification': 'Notify authorities within 72 hours',
            'pia': 'Conduct privacy impact assessments',
            'dpo': 'Appoint a Data Protection Officer if required'
        }
    }
}

def check_compliance(org_data, framework):
    """Check an organization's controls against a framework."""
    controls = COMPLIANCE_CONTROLS.get(framework, {})
    gaps = []
    compliant = []

    for category, requirements in controls.items():
        for control_id, requirement in requirements.items():
            if org_data.get(control_id, False):
                compliant.append((category, control_id, requirement))
            else:
                gaps.append((category, control_id, requirement))

    return {
        'framework': framework,
        'compliant_count': len(compliant),
        'gap_count': len(gaps),
        'compliance_pct': round(
            len(compliant) / (len(compliant) + len(gaps)) * 100, 1
        ) if (compliant or gaps) else 0,
        'gaps': gaps,
        'compliant': compliant
    }

# Example
org = {'firewall_config': True, 'encrypt_transmission': True,
       'risk_assessment': True, 'breach_notification': False}
result = check_compliance(org, 'PCI_DSS')
print(f"PCI DSS Compliance: {result['compliance_pct']}%")
print(f"Gaps: {result['gap_count']}")
for gap in result['gaps']:
    print(f"  ⚠️ {gap[0]}/{gap[1]}: {gap[2]}")
